def _run_p1_api_verifier_lane_once() -> None:
    global _P1_API_VERIFIER_LANE_RAN
    if _P1_API_VERIFIER_LANE_RAN:
        print("OK: UAA-P1-080 through UAA-P1-086 already passed in cached API verifier lane")
        return
    # Run the shared lane in a clean interpreter. The legacy scan process imports
    # hundreds of contract modules before this point, so reusing that module
    # graph can make FastAPI route discovery depend on verifier import order.
    run_cmd([sys.executable, "scripts/verification/api_lane.py"], env=repo_source_env(ROOT))
    _P1_API_VERIFIER_LANE_RAN = True


def verify_no_openwebui_runtime_or_config_implementation() -> None:
    print("\n[Verifier] Running M21 OpenWebUI contract-only guard...")
    try:
        git_files_raw = subprocess.check_output(["git", "ls-files"], text=True)
        git_files = git_files_raw.splitlines()
    except subprocess.SubprocessError:
        git_files = []

    forbidden_path_fragments = [
        "docker-compose.openwebui",
        "openwebui.config",
        "openwebui-config",
        "openwebui_plugins",
        "openwebui_pipelines",
        "openwebui_functions",
        "openwebui_tools",
        "apps/openwebui/",
        "openwebui/",
    ]
    for rel_path in git_files:
        lowered = rel_path.lower()
        if lowered.startswith("docs/openwebui/"):
            continue
        if any(fragment in lowered for fragment in forbidden_path_fragments):
            print(f"FAIL: Forbidden OpenWebUI runtime/config path tracked in git: {rel_path}")
            sys.exit(1)

    forbidden_dependencies = [
        '"openwebui"',
        '"open-webui"',
        "openwebui==",
        "open-webui==",
    ]
    for rel_path in ["apps/control-center/package.json", "pyproject.toml"]:
        path = ROOT / rel_path
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8").lower()
        for fragment in forbidden_dependencies:
            if fragment in text:
                print(f"FAIL: Forbidden OpenWebUI dependency fragment in {rel_path}: {fragment}")
                sys.exit(1)

    for rel_path in find_openwebui_forbidden_config_path_matches(ROOT):
        print(f"FAIL: Forbidden OpenWebUI runtime/config path outside docs: {rel_path}")
        sys.exit(1)

    for failure in find_openwebui_forbidden_runtime_fragment_failures(ROOT):
        print(f"FAIL: {failure}")
        sys.exit(1)

    print("OK: No OpenWebUI runtime, deployment config, dependency, or execution route implementation detected")

