def verify_post_m100_roadmap_reconciliation() -> None:
    print("\n[Verifier] Running post-M100 roadmap reconciliation guard...")

    def contains_affirmative_fragment(text: str, fragment: Any) -> bool:
        pattern = re.compile(
            rf"\b{re.escape(fragment)}\b",
            re.IGNORECASE,
        )
        negation_tokens = {
            "absence",
            "absent",
            "cannot",
            "cant",
            "can't",
            "didnt",
            "didn't",
            "doesnt",
            "doesn't",
            "dont",
            "don't",
            "never",
            "no",
            "none",
            "not",
            "without",
        }
        for match in pattern.finditer(text):
            prefix = text[max(0, match.start() - 160) : match.start()]
            tokens = re.findall(r"[a-z0-9']+", prefix.lower())[-8:]
            if any(token in negation_tokens for token in tokens):
                continue
            compound_negation = tokens[-2:] in (
                ["does", "not"],
                ["do", "not"],
                ["did", "not"],
                ["can", "not"],
            )
            if len(tokens) >= 2 and compound_negation:
                continue
            return True
